function sectionPermission(tab){if(GP.includes(tab)||tab==='Goal Planner')return'access_goal_planner';if(tab==='Retirement planner'||tab==='RP Reports')return'access_retirement_planner';if(tab==='Policies')return'access_policies';if(SET.includes(tab)||tab==='Settings')return'access_settings';return''}
