const R=n=>Math.round(+n||0),rows=L.map(o=>{const x=o.x,per=x.type?'Auto (no additions)':[ayT(x,' '),matT(x,'')].filter(Boolean).join('; ');
return{name:x.name,cat:x.cat+(x.type?' (auto)':''),cur:R(o.cur),yr:x.type?0:R(x.add),mo:x.type?0:R(x.madd),per,ret:+(x.ret*100).toFixed(2),fv:R(o.fv)}});
const T=rows.reduce((t,r)=>({cur:t.cur+r.cur,yr:t.yr+r.yr,mo:t.mo+r.mo,fv:t.fv+r.fv,w:t.w+r.cur*r.ret}),{cur:0,yr:0,mo:0,fv:0,w:0});
const out=[HCSV_COLS.map(q).join(',')].concat(rows.map(r=>[r.name,r.cat,r.cur,r.yr,r.mo,r.per,r.ret.toFixed(2),r.fv].map(q).join(',')));
