const key=(r,k)=>k==='a'||k[0]==='s'?r.a:k==='year'?r.year:k==='age'?r.age[0]:k==='tot'||k==='hi'?r.tot:k==='roi'?(rowRoi(r)||0):k==='chg'?r.chg:k==='add'?depShow(r.a,null,D.rows.length):k==='pay'?r.pay:k==='ti'?polTiVal(r.a>1?r.chg-r.add:null,r.pay):k==='int'?(r.a>1?r.chg-r.add:-1e18):k==='mi'?(monthlyIncome(r)??-1e18):r.v[+k.slice(1)];
